// 1.8.0 主题主视觉：每个主题一幅大尺寸标志性建筑 / 原创角色场景。
// 场景数据由 SVG 风格路径描述（M L Q C Z），启动后只解析一次；绘制为一次性静态 Canvas，无计时器、无动画。
// 现实地标（八坂塔、伏见稻荷鸟居、东京塔、东京天空树、江之岛灯塔、富士山、平等院凤凰堂、道后温泉、姬路城）
// 与原创角色（废墟流浪者、废土机器人、狐像、灯笼精灵、茶碗精灵、苔藓精灵、宇航猫等）均为原创绘制。

struct HeroShape: Sendable {
    let d: String
    let fill: String?
    let stroke: String?
    let lw: CGFloat
    let clip: Int      // 0 普通；1 开始裁剪（d 为裁剪轮廓）；2 结束裁剪
}

struct HeroParsedShape {
    let path: Path
    let fill: (token: String, alpha: Double)?
    let stroke: (token: String, alpha: Double)?
    let lw: CGFloat
    let clip: Int
}

enum HeroScenes {
    static func parseColor(_ raw: String?) -> (token: String, alpha: Double)? {
        guard let raw else { return nil }
        let parts = raw.split(separator: "@", maxSplits: 1).map(String.init)
        return (parts[0], parts.count > 1 ? (Double(parts[1]) ?? 1) : 1)
    }

    /// 只支持绝对坐标的 M L Q C Z。
    static func parsePath(_ d: String) -> Path {
        var spaced = ""
        spaced.reserveCapacity(d.count * 2)
        for ch in d {
            if "MLQCZ".contains(ch) { spaced.append(" "); spaced.append(ch); spaced.append(" ") } else { spaced.append(ch) }
        }
        var path = Path()
        var nums: [CGFloat] = []
        var cmd: Character = "M"
        func need(_ c: Character) -> Int { c == "M" || c == "L" ? 2 : (c == "Q" ? 4 : (c == "C" ? 6 : 0)) }
        func run() {
            let n = need(cmd)
            while n > 0 && nums.count >= n {
                let v = Array(nums.prefix(n)); nums.removeFirst(n)
                switch cmd {
                case "M": path.move(to: CGPoint(x: v[0], y: v[1])); cmd = "L"
                case "L": path.addLine(to: CGPoint(x: v[0], y: v[1]))
                case "Q": path.addQuadCurve(to: CGPoint(x: v[2], y: v[3]), control: CGPoint(x: v[0], y: v[1]))
                case "C": path.addCurve(to: CGPoint(x: v[4], y: v[5]), control1: CGPoint(x: v[0], y: v[1]), control2: CGPoint(x: v[2], y: v[3]))
                default: break
                }
            }
        }
        for token in spaced.split(whereSeparator: { $0 == " " || $0 == "," }) {
            if token.count == 1, let c = token.first, "MLQCZ".contains(c) {
                run()
                if c == "Z" { path.closeSubpath() } else { cmd = c; nums.removeAll() }
            } else if let v = Double(token) {
                nums.append(CGFloat(v))
            }
        }
        run()
        return path
    }

    nonisolated(unsafe) static let parsed: [String: [HeroParsedShape]] = {
        var out: [String: [HeroParsedShape]] = [:]
        for (key, shapes) in sources {
            out[key] = shapes.map { HeroParsedShape(path: parsePath($0.d), fill: parseColor($0.fill), stroke: parseColor($0.stroke), lw: $0.lw, clip: $0.clip) }
        }
        return out
    }()

    static func has(_ system: String) -> Bool { sources[system] != nil }

