/// 主视觉层：右下角锚定，随窗口缩放；左侧与上方留给内容。
struct HeroSceneLayer: View {
    let system: String
    let accent: Color
    let ink: Color
    let alpha: Double

    private func resolve(_ spec: (token: String, alpha: Double)) -> Color {
        let base: Color
        switch spec.token {
        case "A": base = accent
        case "I": base = ink
        default:
            let hex = String(spec.token.dropFirst())
            let n = UInt32(hex, radix: 16) ?? 0
            base = Color(.sRGB, red: Double((n >> 16) & 255) / 255, green: Double((n >> 8) & 255) / 255, blue: Double(n & 255) / 255, opacity: 1)
        }
        return base.opacity(spec.alpha)
    }

    private func drawShape(_ shape: HeroParsedShape, in context: inout GraphicsContext) {
        if let fill = shape.fill { context.fill(shape.path, with: .color(resolve(fill))) }
        if let stroke = shape.stroke {
            context.stroke(shape.path, with: .color(resolve(stroke)),
                           style: StrokeStyle(lineWidth: max(0.6, shape.lw), lineCap: .round, lineJoin: .round))
        }
    }

    var body: some View {
        Canvas { context, size in
            guard let shapes = HeroScenes.parsed[system], size.width > 40, size.height > 40 else { return }
            let scale = min(size.width * 0.66, size.height * 0.97) / 1000
            let originX = size.width - 1000 * scale - min(14, size.width * 0.02)
            let originY = size.height - 990 * scale
            context.opacity = 0.34 + 0.62 * max(0.25, min(1, alpha))
            context.translateBy(x: originX, y: originY)
            context.scaleBy(x: scale, y: scale)
            var i = 0
            while i < shapes.count {
                let shape = shapes[i]
                if shape.clip == 1 {
                    var j = i + 1
                    while j < shapes.count && shapes[j].clip != 2 { j += 1 }
                    let inner = Array(shapes[(i + 1)..<min(j, shapes.count)])
                    context.drawLayer { layer in
                        layer.clip(to: shape.path)
                        for item in inner { drawShape(item, in: &layer) }
                    }
                    i = j + 1
                    continue
                }
                drawShape(shape, in: &context)
                i += 1
            }
        }
    }
}
